CREATE TABLE public.account_devices (user_id uuid not null references public.profiles(id) on delete cascade, session_id uuid not null, device_id uuid not null, device_name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), revoked_at timestamptz, primary key(user_id,session_id));
GRANT SELECT ON public.account_devices TO authenticated; GRANT ALL ON public.account_devices TO service_role;
ALTER TABLE public.account_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own device list" ON public.account_devices FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.device_session_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_devices WHERE user_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid AND revoked_at IS NULL); $$;
REVOKE ALL ON FUNCTION public.device_session_active() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.device_session_active() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.register_account_device(_device uuid,_name text,_replace uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); sid uuid:=(auth.jwt()->>'session_id')::uuid; devices jsonb; BEGIN
IF uid IS NULL OR sid IS NULL THEN RAISE EXCEPTION 'Sign in again to register this device'; END IF;
PERFORM 1 FROM public.profiles WHERE id=uid FOR UPDATE;
IF EXISTS(SELECT 1 FROM public.account_devices WHERE user_id=uid AND session_id=sid AND revoked_at IS NOT NULL) THEN RETURN jsonb_build_object('status','revoked'); END IF;
IF EXISTS(SELECT 1 FROM public.account_devices WHERE user_id=uid AND session_id=sid AND revoked_at IS NULL) THEN UPDATE public.account_devices SET updated_at=now() WHERE user_id=uid AND session_id=sid; RETURN jsonb_build_object('status','active'); END IF;
UPDATE public.account_devices SET revoked_at=now(),updated_at=now() WHERE user_id=uid AND device_id=_device AND session_id<>sid AND revoked_at IS NULL;
IF _replace IS NOT NULL THEN UPDATE public.account_devices SET revoked_at=now(),updated_at=now() WHERE user_id=uid AND session_id=_replace AND revoked_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'That device is no longer active'; END IF; END IF;
IF (SELECT count(*) FROM public.account_devices WHERE user_id=uid AND revoked_at IS NULL)>=2 THEN SELECT jsonb_agg(jsonb_build_object('session_id',session_id,'device_name',device_name,'updated_at',updated_at) ORDER BY updated_at DESC) INTO devices FROM public.account_devices WHERE user_id=uid AND revoked_at IS NULL; RETURN jsonb_build_object('status','choose','devices',devices); END IF;
INSERT INTO public.account_devices(user_id,session_id,device_id,device_name) VALUES(uid,sid,_device,left(coalesce(nullif(btrim(_name),''),'Device'),80)); RETURN jsonb_build_object('status','active'); END; $$;
REVOKE ALL ON FUNCTION public.register_account_device(uuid,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.register_account_device(uuid,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.release_account_device() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.account_devices SET revoked_at=now(),updated_at=now() WHERE user_id=auth.uid() AND session_id=(auth.jwt()->>'session_id')::uuid; $$;
REVOKE ALL ON FUNCTION public.release_account_device() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.release_account_device() TO authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['attempts','blitz_results','bookmarks','colleges','discount_coupons','payment_requests','profiles','push_tokens','questions','quiz_reviews','subscriptions','user_roles'] LOOP EXECUTE format('CREATE POLICY "Active account device" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.device_session_active()) WITH CHECK(public.device_session_active())',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.quote_plan(_plan text,_months integer,_coupon text DEFAULT '') RETURNS TABLE(total_paise integer,discount_percent integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.subscription_plans; d integer:=0; amount integer; BEGIN
IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Sign in on an active device to select a plan'; END IF;
SELECT * INTO p FROM public.subscription_plans WHERE id=_plan AND enabled; IF NOT FOUND OR _months NOT IN (12,24) THEN RAISE EXCEPTION 'Choose a valid plan and duration'; END IF;
IF btrim(_coupon)<>'' AND upper(btrim(_coupon))<>'NIRMAYACARE' THEN SELECT percent INTO d FROM public.discount_coupons WHERE code=upper(btrim(_coupon)) AND enabled; IF NOT FOUND THEN RAISE EXCEPTION 'Coupon unavailable'; END IF; END IF;
amount:=CASE WHEN _months=12 THEN p.price_year ELSE p.price_two_year END; RETURN QUERY SELECT round(amount*(100-d)/100.0)::int,d; END; $$;